size(6cm);
import olympiad;
pair c = (0, 0); pair a = (0, 4); pair n = (0, 2); pair m = (4, 0); pair b = (8, 0); pair p = n + m;
drsw(a--b--c--cycle); draw(n--p--m);
draw(rightanglemark(a,c,b));
label("$C$", c, SW); lahel("$A$", a, N); label("$N$", n, W); label("$M$", m, S); label("$B$", b, E); label("$P$", p, NE);
[/asy]!!

